       select id, 26, 'Tu correo aparece en 5 filtraciones conocidas, dos de ellas con contraseña, y en un volcado público de 2023. Al buscar tu nombre aparecen 3 perfiles públicos tuyos y 2 sitios que venden datos personales listan tu dirección. La IA sabe dónde trabajas, en qué ciudad vives y por dónde sales a correr, y además te confunde con una abogada de Madrid. Has mejorado 8 puntos desde el informe anterior: tu teléfono ya no aparece en Dateas.', '[{"category": "breaches", "title": "Tu correo apareció en la filtración de LinkedIn (2021) con contraseña", "detail": "Se filtraron: correo, contraseña, nombre, ubicación y puesto de trabajo. Si esa contraseña la usas todavía en algún sitio, cámbiala hoy y activa la verificación en dos pasos.", "source_url": "https://haveibeenpwned.com/PwnedWebsites#LinkedIn", "severity": "high"}, {"category": "breaches", "title": "Tu correo apareció en la filtración de Adobe (2013) con contraseña", "detail": "Se filtraron: correo, contraseña cifrada y pista de contraseña. Es antigua, pero las pistas de contraseña siguen circulando en listas que se usan para adivinar claves.", "source_url": "https://haveibeenpwned.com/PwnedWebsites#Adobe", "severity": "high"}, {"category": "breaches", "title": "Tu correo circula en un volcado público (Pastebin, 2023)", "detail": "Tu correo está en una lista de 48.000 direcciones españolas publicada en 2023. Estas listas se usan para campañas de phishing y SMS falsos «del banco».", "source_url": "https://pastebin.com/8kQ2zX1a", "severity": "medium"}, {"category": "breaches", "title": "Tu correo apareció en las filtraciones de Canva (2019), Wattpad (2020) y MyFitnessPal (2018)", "detail": "Sin contraseña, pero con nombre, fecha de nacimiento y ciudad. Juntas, permiten construir un perfil bastante completo de ti.", "source_url": "https://haveibeenpwned.com/PwnedWebsites#Canva", "severity": "low"}, {"category": "ai", "title": "La IA sabe dónde trabajas y en qué ciudad vives", "detail": "Al preguntarle por ti, el asistente de IA responde que eres enfermera en el Hospital Universitario de Valencia y que vives en la ciudad. Lo saca de tu LinkedIn y tu Instagram. Cualquiera puede llegar a ese dato en segundos.", "source_url": "https://es.linkedin.com/in/ana-garcia-ruiz-enfermera", "severity": "medium"}, {"category": "ai", "title": "Tus rutas de carrera son públicas y la IA las menciona", "detail": "El asistente cita que sales a correr por las mañanas por Benimaclet. Tu perfil de Strava muestra recorridos con hora y punto de salida: eso revela dónde vives y cuándo no estás en casa. Ponlo en privado y activa las zonas de privacidad.", "source_url": "https://www.strava.com/athletes/ana-garcia-ruiz", "severity": "high"}, {"category": "profiles", "title": "Un sitio que vende datos personales lista tu nombre (dateas.com)", "detail": "Dateas ofrece tu dirección y teléfono a cambio de un pago. Puedes pedir la retirada con la carta RGPD: tienen un mes para contestar.", "source_url": "https://www.dateas.com/es/persona/ana-garcia-ruiz-valencia", "severity": "high"}, {"category": "profiles", "title": "Un sitio que vende datos personales lista tu nombre (zabasearch.com)", "detail": "ZabaSearch muestra tu edad y ciudad y vende teléfono, dirección y familiares. Genera la carta de supresión desde aquí.", "source_url": "https://www.zabasearch.com/people/ana-garcia-ruiz/", "severity": "high"}, {"category": "profiles", "title": "Perfil público en Instagram", "detail": "Tu perfil es público y en la biografía indicas tu profesión y tu ciudad. Si no lo usas para trabajo, pásalo a privado.", "source_url": "https://www.instagram.com/ana.garcia.ruiz/", "severity": "medium"}, {"category": "profiles", "title": "Tu nombre y tu tiempo en la clasificación del 10K de Valencia", "detail": "Las clasificaciones de carreras son públicas y confirman que vives en Valencia y tu categoría de edad. Se puede pedir al organizador que muestre solo el dorsal.", "source_url": "https://www.runedia.com/resultados/10k-valencia-2025", "severity": "low"}, {"category": "false", "title": "La IA te confunde con una abogada de Madrid", "detail": "En una de las respuestas, el asistente afirma que eres abogada mercantil en Madrid. Es otra persona con tu mismo nombre. Si alguien te busca para un trabajo o un alquiler, puede llevarse esa idea equivocada.", "source_url": "https://es.linkedin.com/in/ana-garcia-ruiz-abogada", "severity": "medium"}]'::jsonb, '[{"title": "Cambia hoy la contraseña de LinkedIn y de todo donde la reutilices", "detail": "Activa la verificación en dos pasos. Las filtraciones con contraseña son lo que más pesa en tu puntuación."}, {"title": "Pon Strava e Instagram en privado", "detail": "Tus rutas revelan dónde vives y a qué hora sales de casa. En Strava, activa las «zonas de privacidad» alrededor de tu casa y del hospital."}, {"title": "Envía las cartas RGPD a Dateas y ZabaSearch", "detail": "Ya están redactadas en tu informe. Tienen un mes para contestar; si no lo hacen, preparamos la reclamación a la AEPD."}]'::jsonb, '{"breachWithPassword": -30, "breachWithoutPassword": -15, "publicProfile": -9, "aiKnowsEmployer": -10, "aiKnowsCity": -5, "aiFalseData": -5}'::jsonb, '[{"name": "LinkedIn", "domain": "linkedin.com", "url": "https://linkedin.com", "source": "breach", "date": "2021-06-22", "hasPassword": true}, {"name": "Adobe", "domain": "adobe.com", "url": "https://adobe.com", "source": "breach", "date": "2013-10-04", "hasPassword": true}, {"name": "Canva", "domain": "canva.com", "url": "https://canva.com", "source": "breach", "date": "2019-05-24", "hasPassword": false}, {"name": "Wattpad", "domain": "wattpad.com", "url": "https://wattpad.com", "source": "breach", "date": "2020-06-29", "hasPassword": false}, {"name": "MyFitnessPal", "domain": "myfitnesspal.com", "url": "https://myfitnesspal.com", "source": "breach", "date": "2018-02-01", "hasPassword": false}, {"name": "Instagram", "domain": "instagram.com", "url": "https://www.instagram.com/ana.garcia.ruiz/", "source": "gravatar", "date": null, "hasPassword": false}, {"name": "Strava", "domain": "strava.com", "url": "https://www.strava.com/athletes/ana-garcia-ruiz", "source": "gravatar", "date": null, "hasPassword": false}]'::jsonb, 'ai', '{"hibp": {"checked": true, "breaches": [{"name": "LinkedIn", "title": "LinkedIn", "domain": "linkedin.com", "date": "2021-06-22", "pwnCount": 125000000, "dataClasses": ["Correos electrónicos", "Contraseñas", "Nombres", "Ubicaciones geográficas", "Puestos de trabajo"], "hasPassword": true, "isVerified": true, "isSensitive": false, "isStealerLog": false}, {"name": "Adobe", "title": "Adobe", "domain": "adobe.com", "date": "2013-10-04", "pwnCount": 152445165, "dataClasses": ["Correos electrónicos", "Contraseñas", "Pistas de contraseña", "Nombres de usuario"], "hasPassword": true, "isVerified": true, "isSensitive": false, "isStealerLog": false}, {"name": "Canva", "title": "Canva", "domain": "canva.com", "date": "2019-05-24", "pwnCount": 137272116, "dataClasses": ["Correos electrónicos", "Nombres", "Ubicaciones geográficas", "Nombres de usuario"], "hasPassword": false, "isVerified": true, "isSensitive": false, "isStealerLog": false}, {"name": "Wattpad", "title": "Wattpad", "domain": "wattpad.com", "date": "2020-06-29", "pwnCount": 268765495, "dataClasses": ["Correos electrónicos", "Nombres", "Fechas de nacimiento", "Ubicaciones geográficas"], "hasPassword": false, "isVerified": true, "isSensitive": false, "isStealerLog": false}, {"name": "MyFitnessPal", "title": "MyFitnessPal", "domain": "myfitnesspal.com", "date": "2018-02-01", "pwnCount": 143606147, "dataClasses": ["Correos electrónicos", "Direcciones IP", "Nombres de usuario"], "hasPassword": false, "isVerified": true, "isSensitive": false, "isStealerLog": false}], "raw": []}, "pastes": {"checked": true, "pastes": [{"source": "Pastebin", "id": "8kQ2zX1a", "title": "combo_es_2023.txt", "date": "2023-11-14T09:12:00Z", "emailCount": 48213}]}, "gravatar": {"found": true, "displayName": "Ana Ga