select 'usuario' as k, count(*) from public.users where email = 'demo@rastropro.com'
union all select 'informes', count(*) from public.reports r join public.requests q on q.id = r.request_id where q.email = 'demo@rastropro.com'
union all select 'servicios gmail', jsonb_array_length(services) from public.mailbox_scans s join public.users u on u.id = s.user_id where u.email = 'demo@rastropro.com'
union all select 'cartas', count(*) from public.letters l join public.users u on u.id = l.user_id where u.email = 'demo@rastropro.com'
union all select 'comprobaciones diarias', count(*) from public.daily_checks d join public.users u on u.id = d.user_id where u.email = 'demo@rastropro.com';
